// ===== STORYMAKER MODULE =====
const _loadStoryBase=load;
load=async function(){await _loadStoryBase();if(M?.role==='team'){try{let a=await Promise.all([api('/rest/v1/storymaker_briefings?select=*&order=created_at.desc'),api('/rest/v1/storymaker_checklist_items?select=*&order=sort_order.asc,created_at.asc'),api('/rest/v1/storymaker_deliverables?select=*&order=sort_order.asc,created_at.asc')]);D.storyBriefings=a[0]||[];D.storyChecklist=a[1]||[];D.storyDeliverables=a[2]||[]}catch(e){console.warn('storymaker load',e);D.storyBriefings=[];D.storyChecklist=[];D.storyDeliverables=[]}}};

const storyStyle=document.createElement('style');storyStyle.textContent=`.story-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.story-card{position:relative;overflow:hidden}.story-card:before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--o)}.story-meta{display:flex;gap:7px;flex-wrap:wrap;margin:10px 0}.story-progress{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:12px}.story-progress div{padding:10px;border:1px solid #292929;border-radius:12px;background:#121212}.story-progress small{display:block;color:#777;font-size:9px}.story-progress b{display:block;margin-top:3px}.story-tabs{display:flex;gap:7px;overflow:auto;margin:12px 0}.story-tabs span{white-space:nowrap;padding:7px 10px;border-radius:999px;background:#191919;border:1px solid #292929;font-size:9px}.story-section{margin-top:14px;padding-top:14px;border-top:1px solid #292929}.story-line{display:flex;gap:10px;align-items:flex-start;padding:9px 0;border-bottom:1px solid #222}.story-line input{margin-top:3px}.story-line .grow small{display:block;color:#777;margin-top:2px}.story-priority{color:#ff8a4c}.story-public{min-height:100vh;background:#0e0e0e;color:#fff;padding:24px 14px}.story-public .wrap{max-width:760px;margin:auto}.story-public .hero{padding:28px;border-radius:24px;background:linear-gradient(145deg,#171717,#101010);border:1px solid #282828}.story-public h1{font-size:34px;line-height:1;margin:8px 0}.story-public .block{margin-top:14px;padding:20px;border-radius:18px;background:#151515;border:1px solid #292929}.story-public label{display:block;font-size:11px;font-weight:800;margin:12px 0 5px}.story-public input,.story-public textarea{width:100%;background:#0c0c0c;color:#fff;border:1px solid #333;border-radius:11px;padding:11px}.story-public textarea{min-height:100px}.story-public .checks{display:grid;grid-template-columns:1fr 1fr;gap:8px}.story-public .check{display:flex;align-items:center;gap:8px;padding:10px;border:1px solid #292929;border-radius:11px}.story-public .check input{width:auto}.story-delivery{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.story-delivery a,.story-delivery div{padding:12px;border-radius:12px;background:#101010;border:1px solid #292929;color:#fff;text-decoration:none}@media(max-width:680px){.story-grid{grid-template-columns:1fr}.story-progress{grid-template-columns:1fr 1fr}.story-public .checks,.story-delivery{grid-template-columns:1fr}}`;document.head.appendChild(storyStyle);

productionPage=function(){let ev=(D.events||[]).filter(e=>['storymaker','recording','event'].includes(e.event_type)).filter(e=>!productionClient||e.client_id===productionClient);return`<div class="toolbar"><div><small class="ey">STORYMAKER</small><h2 style="margin:5px 0">Eventos & coberturas</h2><p class="muted">Briefing, captação, entregas e arquivos de cada evento em um só lugar.</p></div><button class="btn pri" data-m="eventNew">＋ Novo evento</button></div><div class="filters"><select id="productionClient"><option value="">Todos</option>${D.clients.filter(c=>c.active).map(c=>`<option value="${c.id}" ${productionClient===c.id?'selected':''}>${E(c.name)}</option>`).join('')}</select></div><div class="story-grid">${ev.map(e=>{let b=(D.storyBriefings||[]).find(x=>x.event_id===e.id),checks=(D.storyChecklist||[]).filter(x=>x.event_id===e.id),del=(D.storyDeliverables||[]).filter(x=>x.event_id===e.id),done=checks.filter(x=>x.completed).length,delDone=del.filter(x=>x.status==='delivered').length,rec=(D.receivables||[]).filter(x=>x.event_id===e.id&&x.status==='pending').reduce((s,x)=>s+Number(x.amount||0),0);return`<section class="panel story-card"><div class="head"><div><small class="ey">${E(lab(e.event_type))}</small><h3>${E(e.title)}</h3><p class="muted">${E(cl(e.client_id)?.name||'Evento avulso')} · ${fmtDate(String(e.starts_at||'').slice(0,10))}</p></div><button class="btn ghost small" onclick="openStoryEvent('${e.id}')">Abrir</button></div><div class="story-meta"><span class="tag ${b?.submitted_at?'g':'y'}">${b?.submitted_at?'Briefing recebido':'Briefing pendente'}</span><span class="tag">${e.location?E(e.location):'Local a definir'}</span></div><div class="story-progress"><div><small>CAPTAÇÃO</small><b>${done}/${checks.length}</b></div><div><small>ENTREGAS</small><b>${delDone}/${del.length}</b></div><div><small>A RECEBER</small><b>${money(rec)}</b></div></div></section>`}).join('')||'<div class="empty">Nenhum evento StoryMaker cadastrado.</div>'}</div>`};

async function ensureStoryBriefing(eventId){let b=(D.storyBriefings||[]).find(x=>x.event_id===eventId);if(b)return b;let e=D.events.find(x=>x.id===eventId);let r=await api('/rest/v1/storymaker_briefings',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({organization_id:M.organization_id,event_id:eventId,partner_names:e?.title||null})});await load();return r[0]}
function storyPublicUrl(token){return location.origin+'/?story='+token}
async function copyStoryBriefing(eventId){try{let b=await ensureStoryBriefing(eventId),u=storyPublicUrl(b.public_token);await navigator.clipboard.writeText(u);toast('Link do briefing copiado')}catch(e){toast(e.message)}}
function openStoryEvent(id){MD={type:'storymakerDetail',id};render()}
const _storyModalBase=modal;
modal=function(){if(MD?.type==='storymakerDetail')return storymakerDetailModal(MD.id);return _storyModalBase()};
function storymakerDetailModal(id){let e=D.events.find(x=>x.id===id);if(!e)return'';let b=(D.storyBriefings||[]).find(x=>x.event_id===id),checks=(D.storyChecklist||[]).filter(x=>x.event_id===id),del=(D.storyDeliverables||[]).filter(x=>x.event_id===id),rec=(D.receivables||[]).filter(x=>x.event_id===id),refs=(b?.reference_links||'').split(/\n+/).filter(Boolean);return`<div class="modalbg"><div class="modal wide"><div class="head"><div><small class="ey">STORYMAKER</small><h2>${E(e.title)}</h2><p class="muted">${fmtDate(String(e.starts_at||'').slice(0,10))}${e.location?' · '+E(e.location):''}</p></div><button class="btn ghost small" data-close>✕</button></div><div class="story-tabs"><span>Visão geral</span><span>Briefing</span><span>Captação</span><span>Entregas</span><span>Arquivos</span></div><section class="panel"><div class="head"><div><small class="ey">BRIEFING DOS NOIVOS / CLIENTE</small><h3>${b?.submitted_at?'Recebido ✓':'Aguardando preenchimento'}</h3></div><div class="actions"><button class="btn ghost small" onclick="copyStoryBriefing('${id}')">Copiar link</button><button class="btn ghost small" data-eventedit="${id}">Editar evento</button></div></div>${b?`<p class="muted">${b.partner_names?E(b.partner_names):'Sem nomes informados'}${b.submitted_at?' · enviado '+notificationWhen(b.submitted_at):''}</p>${b.must_capture?`<div class="note"><b>O que não pode passar ❤️</b><br>${E(b.must_capture)}</div>`:''}${b.important_people?`<div class="note"><b>Pessoas importantes</b><br>${E(b.important_people)}</div>`:''}${b.surprises?`<div class="note"><b>Surpresas ⚠️</b><br>${E(b.surprises)}</div>`:''}${refs.length?`<div class="chips">${refs.map((u,i)=>`<a class="btn ghost small" href="${E(u.trim())}" target="_blank" rel="noopener">Referência ${i+1} ↗</a>`).join('')}</div>`:''}`:'<p class="muted">Clique em “Copiar link” para criar e enviar o briefing privado deste evento.</p>'}</section><section class="story-section"><div class="head"><div><small class="ey">CAPTAÇÃO</small><h3>Checklist do dia</h3></div><button class="btn ghost small" onclick="addStoryCheck('${id}')">＋ Item</button></div>${checks.map(x=>`<label class="story-line"><input type="checkbox" ${x.completed?'checked':''} onchange="toggleStoryCheck('${x.id}',this.checked)"><div class="grow"><b class="${x.priority==='urgent'||x.priority==='high'?'story-priority':''}">${E(x.title)}</b><small>${x.source==='briefing'?'Prioridade do briefing':'Checklist da equipe'} · ${E(x.category)}</small></div></label>`).join('')||'<div class="empty">O checklist será alimentado pelo briefing ou pela equipe.</div>'}</section><section class="story-section"><div class="head"><div><small class="ey">ESCOPO & ENTREGAS</small><h3>O que foi combinado</h3></div><button class="btn ghost small" onclick="addStoryDeliverable('${id}')">＋ Entrega</button></div>${del.map(x=>`<div class="story-line"><div class="grow"><b>${E(x.title)}${x.quantity?' · '+x.quantity+'x':''}</b><small>${E(x.deliverable_type)} · ${x.status==='delivered'?'Entregue':'Pendente'}</small></div><button class="btn ${x.status==='delivered'?'ghost':'pri'} small" onclick="toggleStoryDeliverable('${x.id}','${x.status}')">${x.status==='delivered'?'Reabrir':'Marcar entregue'}</button></div>`).join('')||'<div class="empty">Adicione stories em tempo real, making of, cerimônia, trends, Reels, vídeos editados ou outros combinados.</div>'}</section><section class="story-section"><small class="ey">ARQUIVOS / DRIVE</small><h3>Entrega ao cliente</h3><div class="story-delivery">${[['Material bruto',e.delivery_raw_url],['Vídeos editados',e.delivery_edited_url],['Fotos',e.delivery_photos_url],['Pasta completa',e.delivery_folder_url]].filter(x=>x[1]).map(([n,u])=>`<a href="${E(u)}" target="_blank" rel="noopener"><b>${E(n)}</b><br><small>Abrir Drive ↗</small></a>`).join('')||'<div><b>Nenhum link ainda</b><br><small>Adicione no evento quando a entrega estiver pronta.</small></div>'}</div></section><section class="story-section"><small class="ey">FINANCEIRO</small><h3>Recebimentos vinculados</h3>${rec.map(r=>`<div class="row"><div class="grow"><b>${money(r.amount)}</b><small>${E(r.description)} · ${fmtDate(r.due_date)}</small></div><span class="tag ${r.status==='paid'?'g':'y'}">${r.status==='paid'?'Pago':'Pendente'}</span></div>`).join('')||'<div class="empty">Nenhum recebimento vinculado a este evento.</div>'}</section></div></div>`}
async function addStoryCheck(eventId){let t=prompt('O que precisa ser captado?');if(!t)return;try{await api('/rest/v1/storymaker_checklist_items',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:M.organization_id,event_id:eventId,title:t,category:'capture',source:'team',priority:'normal'})});await load();openStoryEvent(eventId)}catch(e){toast(e.message)}}
async function toggleStoryCheck(id,completed){try{await patch('storymaker_checklist_items',id,{completed,updated_at:new Date().toISOString()});let x=(D.storyChecklist||[]).find(v=>v.id===id);if(x)x.completed=completed}catch(e){toast(e.message)}}
async function addStoryDeliverable(eventId){let t=prompt('Entrega combinada (ex.: Stories em tempo real, Reels, vídeo editado, making of):');if(!t)return;let q=prompt('Quantidade (opcional):','1');try{await api('/rest/v1/storymaker_deliverables',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({organization_id:M.organization_id,event_id:eventId,title:t,deliverable_type:t.toLowerCase(),quantity:Number(q)||null})});await load();openStoryEvent(eventId)}catch(e){toast(e.message)}}
async function toggleStoryDeliverable(id,status){try{await patch('storymaker_deliverables',id,{status:status==='delivered'?'pending':'delivered',updated_at:new Date().toISOString()});let d=(D.storyDeliverables||[]).find(x=>x.id===id);await load();if(d)openStoryEvent(d.event_id);else render()}catch(e){toast(e.message)}}

async function storyPublicBoot(token){R.innerHTML='<div class="story-public"><div class="wrap"><div class="empty">Carregando briefing...</div></div></div>';try{let r=await tf(B+'/rest/v1/rpc/storymaker_public_get',{method:'POST',headers:{apikey:K,'Content-Type':'application/json'},body:JSON.stringify({p_token:token})});let x=await r.json();if(!r.ok||!x)throw Error('Link inválido ou indisponível');renderStoryPublic(x,token)}catch(e){R.innerHTML=`<div class="story-public"><div class="wrap"><div class="block"><h2>Não conseguimos abrir este briefing.</h2><p>${E(e.message)}</p></div></div></div>`}}
// ===== STORYMAKER BRIEFING EXPERIENCE =====
const storyBriefStyle=document.createElement('style');storyBriefStyle.textContent=`
.story-public{padding:14px 10px 42px;background:#090909}.story-public .wrap{max-width:720px}.story-public .hero{padding:28px 22px;border-radius:25px;background:radial-gradient(circle at 86% 12%,rgba(255,106,0,.18),transparent 35%),linear-gradient(145deg,#19130f,#111);border:1px solid #3c2619}.story-public .hero h1{text-transform:uppercase;letter-spacing:-1px;margin:9px 0 4px}.story-public .event-date{color:var(--o);font-size:15px;font-weight:950;letter-spacing:2px}.story-public .event-place{color:#aaa;font-size:11px;margin-top:7px}.story-public .intro{font-size:14px;line-height:1.65;color:#d0d0d0;margin:18px 0 0}.brief-progress{margin:16px 2px 8px}.brief-progress-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;color:#8e8e8e;font-size:9px;font-weight:900;letter-spacing:1px}.brief-progress-track{height:4px;border-radius:999px;background:#222;overflow:hidden}.brief-progress-track i{display:block;height:100%;background:var(--o);border-radius:999px;transition:width .25s ease}.brief-step{display:none}.brief-step.on{display:block;animation:briefIn .22s ease}.story-public .block{padding:22px 18px;border-radius:20px;background:#141414;border:1px solid #292929}.story-public .block.featured{border-color:#75401f;background:linear-gradient(145deg,#1d120c,#141414)}.story-public .block h2{font-size:24px;margin:7px 0 5px}.story-public .block>p{color:#999;line-height:1.55;margin:4px 0 15px}.story-public label{font-size:11px;margin-top:14px}.story-public input,.story-public textarea,.story-public select{width:100%;background:#0b0b0b;color:#fff;border:1px solid #363636;border-radius:12px;padding:12px;font:inherit}.story-public textarea{min-height:92px;resize:vertical}.story-public select{-webkit-appearance:none;appearance:none}.brief-actions{display:flex;justify-content:space-between;gap:9px;margin-top:14px}.brief-actions .btn{min-height:44px}.choice-grid{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.choice-pill{display:flex!important;align-items:center;gap:7px;margin:0!important;padding:10px 12px!important;border:1px solid #383838;border-radius:999px;background:#0e0e0e}.choice-pill:has(input:checked){border-color:var(--o);background:#24150d;color:#fff}.choice-pill input{width:auto!important;margin:0}.brief-two{display:grid;grid-template-columns:1fr 1fr;gap:9px}.brief-toggle{display:flex!important;align-items:flex-start;gap:9px;margin:9px 0!important;padding:12px;border:1px solid #303030;border-radius:13px;background:#101010}.brief-toggle input{width:auto!important;margin-top:2px}.cerimonial-highlight{padding:14px;border-radius:15px;background:#1d120c;border:1px solid #75401f}.cerimonial-highlight h3{margin:4px 0 0}.repeat-list{display:grid;gap:9px}.repeat-row{padding:12px;border:1px solid #303030;border-radius:14px;background:#0e0e0e}.repeat-row .brief-two{margin-bottom:8px}.repeat-row .remove-row{margin-top:8px}.brief-note{padding:13px;border-radius:13px;background:#1a120d;border:1px solid #56301b;color:#c7c7c7;line-height:1.5}.public-success{min-height:82vh;display:grid;place-items:center;text-align:center}.public-success .block{max-width:620px}.story-op-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.story-op-block{padding:13px;border:1px solid #2d2d2d;border-radius:14px;background:#111}.story-op-block h4{margin:0 0 8px;font-size:12px}.story-op-block ul{margin:0;padding-left:17px}.story-op-block li{margin:5px 0;color:#d8d8d8}.story-op-block a{color:#fff}.story-ref-card{display:block;margin:7px 0;padding:11px;border:1px solid #333;border-radius:11px;background:#0c0c0c;color:#fff;text-decoration:none}.story-ref-card small{display:block;color:#888;margin-top:4px}.confidential-box{margin-top:12px;border-color:#75401f!important;background:#1a100b!important}@keyframes briefIn{from{opacity:.25;transform:translateY(5px)}to{opacity:1;transform:none}}@media(max-width:620px){.story-public .hero{padding:24px 18px}.story-public .hero h1{font-size:31px}.story-public .block h2{font-size:22px}.brief-two,.story-op-grid{grid-template-columns:1fr}.brief-actions .btn{flex:1}.brief-actions .btn:only-child{margin-left:auto}.story-public .checks{grid-template-columns:1fr}}
`;document.head.appendChild(storyBriefStyle);

function sbArr(v){if(Array.isArray(v))return v;if(!v)return[];try{let x=typeof v==='string'?JSON.parse(v):v;return Array.isArray(x)?x:[]}catch(e){return String(v).split(/\n+/).map(x=>x.trim()).filter(Boolean)}}
function sbObj(v){if(v&&typeof v==='object'&&!Array.isArray(v))return v;try{return JSON.parse(v||'{}')||{}}catch(e){return{}}}
function sbRows(kind,rows){rows=rows.length?rows:[{}];if(kind==='reference')return rows.map(r=>`<div class="repeat-row" data-sbrow="reference"><div class="brief-two"><input data-k="link" type="url" value="${E(r.link||r.url||'')}" placeholder="Link do Reel ou TikTok"><input data-k="note" value="${E(r.note||'')}" placeholder="O que gostaram nesse vídeo?"></div><button type="button" class="btn ghost small remove-row" onclick="this.closest('.repeat-row').remove()">Remover</button></div>`).join('');if(kind==='person')return rows.map(r=>`<div class="repeat-row" data-sbrow="person"><div class="brief-two"><input data-k="name" value="${E(r.name||'')}" placeholder="Nome"><input data-k="relation" value="${E(r.relation||'')}" placeholder="Relação com vocês"></div><input data-k="photo_path" value="${E(r.photo_path||'')}" placeholder="Link de uma foto (opcional)"><button type="button" class="btn ghost small remove-row" onclick="this.closest('.repeat-row').remove()">Remover</button></div>`).join('');return rows.map(r=>`<div class="repeat-row" data-sbrow="supplier"><div class="brief-two"><select data-k="category"><option value="">Categoria</option>${['Cerimonial / Assessoria','Fotografia','Videomaker','Espaço','Decoração','DJ / Banda','Beleza','Outro'].map(v=>`<option value="${v}" ${r.category===v?'selected':''}>${v}</option>`).join('')}</select><input data-k="name" value="${E(r.name||'')}" placeholder="Nome"></div><input data-k="instagram" value="${E(r.instagram||'')}" placeholder="@ do Instagram"><button type="button" class="btn ghost small remove-row" onclick="this.closest('.repeat-row').remove()">Remover</button></div>`).join('')}
function sbAddRow(kind){let box=document.querySelector(`[data-sblist="${kind}"]`);if(box)box.insertAdjacentHTML('beforeend',sbRows(kind,[{}]))}
function sbCollect(form,kind){return[...form.querySelectorAll(`[data-sbrow="${kind}"]`)].map(row=>{let o={};row.querySelectorAll('[data-k]').forEach(i=>o[i.dataset.k]=i.value.trim());return o}).filter(o=>Object.values(o).some(Boolean))}
function sbStep(n){let steps=[...document.querySelectorAll('.brief-step')],max=steps.length-1;n=Math.max(0,Math.min(max,n));steps.forEach((x,i)=>x.classList.toggle('on',i===n));let bar=document.getElementById('briefProgress'),txt=document.getElementById('briefProgressText');if(bar)bar.style.width=((n+1)/steps.length*100)+'%';if(txt)txt.textContent=`ETAPA ${n+1} DE ${steps.length}`;window.scrollTo({top:0,behavior:'smooth'})}


const _sbDetailBase=storymakerDetailModal;storymakerDetailModal=function(id){let e=D.events.find(x=>x.id===id),b=(D.storyBriefings||[]).find(x=>x.event_id===id);if(!e||!b?.submitted_at)return _sbDetailBase(id);let checks=(D.storyChecklist||[]).filter(x=>x.event_id===id),del=(D.storyDeliverables||[]).filter(x=>x.event_id===id),rec=(D.receivables||[]).filter(x=>x.event_id===id),must=sbArr(b.must_capture_items),people=sbArr(b.important_people_items),refs=sbArr(b.reference_items),suppliers=sbArr(b.supplier_items),vibes=sbArr(b.vibe_styles);return`<div class="modalbg"><div class="modal wide"><div class="head"><div><small class="ey">STORYMAKER</small><h2>${E(e.title)}</h2><p class="muted">${fmtDate(String(e.starts_at||'').slice(0,10))}${e.location?' · '+E(e.location):''}</p></div><button class="btn ghost small" data-close>✕</button></div><section class="panel"><div class="head"><div><small class="ey">BRIEFING OPERACIONAL</small><h3>Recebido e organizado ✓</h3></div><button class="btn ghost small" onclick="copyStoryBriefing('${id}')">Copiar link</button></div><div class="story-op-grid"><div class="story-op-block"><h4>NÃO PODE PASSAR</h4>${must.length?`<ul>${must.map(x=>`<li>${E(x)}</li>`).join('')}</ul>`:'<span class="muted">Nada informado.</span>'}</div><div class="story-op-block"><h4>PESSOAS IMPORTANTES</h4>${people.length?`<ul>${people.map(p=>`<li><b>${E(p.name)}</b>${p.relation?' — '+E(p.relation):''}</li>`).join('')}</ul>`:'<span class="muted">Ninguém informado.</span>'}</div><div class="story-op-block"><h4>REFERÊNCIAS</h4>${refs.length?refs.map((r,i)=>`<a class="story-ref-card" href="${E(r.link)}" target="_blank" rel="noopener"><b>Referência ${i+1} ↗</b><small>${E(r.note||'Abrir vídeo')}</small></a>`).join(''):'<span class="muted">Sem referências.</span>'}</div><div class="story-op-block"><h4>PREFERÊNCIAS</h4><div class="chips">${vibes.map(v=>`<span class="tag o">${E(v)}</span>`).join('')}</div><small>${b.likes_talking==='yes'?'Gostam de falar nos Stories':b.likes_talking==='no'?'Não gostam de falar nos Stories':''}${b.likes_trends==='yes'?' · Gostam de trends':''}${b.music_important?' · Música: '+E(b.music_important):''}</small></div><div class="story-op-block"><h4>FORNECEDORES</h4>${suppliers.length?suppliers.map(s=>`<p><b>${E(s.category||'Fornecedor')}</b><br><small>${E(s.name||'')}${s.instagram?' · '+E(s.instagram):''}</small></p>`).join(''):'<span class="muted">Nenhum fornecedor.</span>'}</div><div class="story-op-block"><h4>STORIES / DESTAQUES</h4><p>${E(({yes:'Querem salvar nos Destaques',no:'Não querem salvar nos Destaques',unsure:'Ainda não decidiram'})[b.highlights_choice]||'Não informado')}</p><small>${E(b.highlight_details||'')}${b.mark_suppliers?' · Marcar fornecedores':''}${b.repost_permission?' · Repost autorizado':''}${b.publication_permission?' · Publicação Colab autorizada':''}</small></div><div class="story-op-block"><h4>RESTRIÇÕES</h4><p>${E(b.do_not_capture||'Nada informado para filmagem.')}</p><small>${E(b.do_not_publish||'Nada informado para publicação.')}</small></div><div class="story-op-block"><h4>ÚLTIMA OBSERVAÇÃO</h4><p>${E(b.final_notes||'Nada acrescentado.')}</p></div></div></section><section class="panel confidential-box"><small class="ey">INFORMAÇÃO CONFIDENCIAL 🔒</small><h3>Somente equipe Colab</h3><form id="storyConfidentialForm" data-briefing="${b.id}" data-event="${id}"><textarea name="confidential_notes" rows="3" placeholder="Surpresas e informações que nunca aparecem no link público.">${E(b.confidential_notes||'')}</textarea><button class="btn ghost small" style="margin-top:8px">Salvar</button></form></section><section class="story-section"><div class="head"><div><small class="ey">CAPTAÇÃO</small><h3>Prioridades e checklist</h3></div><button class="btn ghost small" onclick="addStoryCheck('${id}')">＋ Item</button></div>${checks.map(x=>`<label class="story-line"><input type="checkbox" ${x.completed?'checked':''} onchange="toggleStoryCheck('${x.id}',this.checked)"><div class="grow"><b class="${x.priority==='urgent'||x.priority==='high'?'story-priority':''}">${E(x.title)}</b><small>${x.source==='briefing'?'Prioridade do briefing':'Checklist da equipe'} · ${E(x.category)}</small></div></label>`).join('')||'<div class="empty">Sem itens.</div>'}</section><section class="story-section"><div class="head"><h3>Entregas</h3><button class="btn ghost small" onclick="addStoryDeliverable('${id}')">＋ Entrega</button></div>${del.map(x=>`<div class="story-line"><div class="grow"><b>${E(x.title)}${x.quantity?' · '+x.quantity+'x':''}</b><small>${x.status==='delivered'?'Entregue':'Pendente'}</small></div><button class="btn ${x.status==='delivered'?'ghost':'pri'} small" onclick="toggleStoryDeliverable('${x.id}','${x.status}')">${x.status==='delivered'?'Reabrir':'Marcar entregue'}</button></div>`).join('')||'<div class="empty">Sem entregas.</div>'}</section><section class="story-section"><small class="ey">ARQUIVOS / DRIVE</small><div class="story-delivery">${[['Material bruto',e.delivery_raw_url],['Vídeos editados',e.delivery_edited_url],['Fotos',e.delivery_photos_url],['Pasta completa',e.delivery_folder_url]].filter(x=>x[1]).map(([n,u])=>`<a href="${E(u)}" target="_blank"><b>${n}</b><br><small>Abrir Drive ↗</small></a>`).join('')||'<div><b>Nenhum link ainda</b></div>'}</div></section><section class="story-section"><small class="ey">FINANCEIRO</small>${rec.map(r=>`<div class="row"><div class="grow"><b>${money(r.amount)}</b><small>${E(r.description)}</small></div><span class="tag ${r.status==='paid'?'g':'y'}">${r.status==='paid'?'Pago':'Pendente'}</span></div>`).join('')||'<div class="empty">Nenhum recebimento vinculado.</div>'}</section></div></div>`};
const storyBriefEnhanceStyle=document.createElement('style');storyBriefEnhanceStyle.textContent=`
.brief-conditional[hidden]{display:none!important}.brief-conditional{padding:12px;margin:8px 0;border-left:2px solid var(--o);background:#101010;border-radius:0 12px 12px 0}.brief-choice-title{display:block;margin:16px 0 8px;font-size:12px;font-weight:900;color:#fff}.ref-summary{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}.ref-summary>div{min-width:0}.ref-summary b{display:block;color:var(--o);font-size:10px;letter-spacing:1px}.ref-summary a{display:block;color:#fff;font-weight:900;text-decoration:none;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:4px}.ref-summary p{margin:5px 0 0;color:#bdbdbd;font-size:12px;line-height:1.45}.ref-editor{margin-top:10px}.repeat-row[data-editing="false"] .ref-editor{display:none}.repeat-row[data-editing="true"] .ref-summary{display:none}.ref-buttons{display:flex;gap:7px;flex-wrap:wrap}.story-priority-label{color:var(--o)!important;font-weight:950!important}.story-op-block.wide{grid-column:1/-1}.story-op-block .op-line{padding:7px 0;border-bottom:1px solid #272727}.story-op-block .op-line:last-child{border-bottom:0}.story-op-block .op-line small{display:block;color:#8d8d8d;margin-top:3px}@media(max-width:620px){.story-op-block.wide{grid-column:auto}.ref-summary{flex-direction:column}.ref-buttons{width:100%}.ref-buttons .btn{flex:1}}
`;document.head.appendChild(storyBriefEnhanceStyle);

function sbRadio(name,value,label,current){return`<label class="choice-pill"><input type="radio" name="${name}" value="${value}" ${current===value?'checked':''}> ${label}</label>`}
function sbNames(b,e){let n=String(e.partner_names||b.partner_names||'').trim(),generic=/^(casamento|evento|wedding)\s*$/i.test(n);return generic?'O GRANDE DIA':n||'O GRANDE DIA'}
function sbRowsV2(kind,rows){rows=rows.length?rows:[{}];if(kind==='reference')return rows.map((r,i)=>`<div class="repeat-row" data-sbrow="reference" data-editing="${r.link||r.url?'false':'true'}"><div class="ref-summary"><div><b data-ref-number>REFERÊNCIA ${String(i+1).padStart(2,'0')}</b><a data-ref-link href="${E(r.link||r.url||'#')}" target="_blank" rel="noopener">${E(sbRefType(r.link||r.url)||'Abrir referência')} ↗</a><p data-ref-note>“${E(r.note||'Sem observação')}”</p><small data-ref-intent>${E(sbIntentLabel(r.intent))}</small></div><div class="ref-buttons"><button type="button" class="btn ghost small" onclick="sbEditRef(this)">Editar</button><button type="button" class="btn ghost small" onclick="sbRemoveRef(this)">Remover</button></div></div><div class="ref-editor"><label>Link do vídeo</label><input data-k="link" type="url" value="${E(r.link||r.url||'')}" placeholder="Cole um link do Instagram, Reel, TikTok ou outra referência"><label>O que você mais gostou nesse vídeo?</label><input data-k="note" value="${E(r.note||'')}" placeholder="Ex.: quero essa cena / essa trend / gostei do jeito espontâneo"><label>Quero fazer algo parecido?</label><select data-k="intent"><option value="">Escolher</option><option value="yes" ${r.intent==='yes'?'selected':''}>Sim</option><option value="inspiration" ${r.intent==='inspiration'?'selected':''}>Só gostei como inspiração</option><option value="unsure" ${r.intent==='unsure'?'selected':''}>Ainda não sei</option></select><div class="ref-buttons" style="margin-top:9px"><button type="button" class="btn pri small" onclick="sbSaveRef(this)">Salvar referência</button><button type="button" class="btn ghost small" onclick="sbRemoveRef(this)">Remover</button></div></div></div>`).join('');if(kind==='person')return rows.map(r=>`<div class="repeat-row" data-sbrow="person"><div class="brief-two"><input data-k="name" value="${E(r.name||'')}" placeholder="Nome"><input data-k="relation" value="${E(r.relation||'')}" placeholder="Relação com vocês"></div><input data-k="photo_path" type="url" value="${E(r.photo_path||'')}" placeholder="Link de uma foto (opcional)"><button type="button" class="btn ghost small remove-row" onclick="this.closest('.repeat-row').remove()">Remover</button></div>`).join('');return rows.map(r=>`<div class="repeat-row" data-sbrow="supplier"><div class="brief-two"><select data-k="category"><option value="">Categoria</option>${['Cerimonial / Assessoria','Fotografia','Videomaker','Espaço','Decoração','DJ / Banda','Beleza','Buffet','Celebrante','Outro'].map(v=>`<option value="${v}" ${r.category===v?'selected':''}>${v}</option>`).join('')}</select><input data-k="name" value="${E(r.name||'')}" placeholder="Nome"></div><input data-k="instagram" value="${E(r.instagram||'')}" placeholder="@ Instagram"><button type="button" class="btn ghost small remove-row" onclick="this.closest('.repeat-row').remove()">Remover</button></div>`).join('')}
function sbRefType(url){url=String(url||'').toLowerCase();if(url.includes('tiktok'))return'TikTok';if(url.includes('instagram')||url.includes('reel'))return'Instagram / Reel';return url?'Link / vídeo':''}
function sbIntentLabel(v){return({yes:'Querem fazer algo parecido',inspiration:'Só como inspiração',unsure:'Ainda não decidiram'})[v]||'Intenção não informada'}
function sbAddRowV2(kind){let box=document.querySelector(`[data-sblist="${kind}"]`);if(!box)return;box.insertAdjacentHTML('beforeend',sbRowsV2(kind,[{}]));if(kind==='reference')sbRenumberRefs()}
function sbEditRef(btn){btn.closest('.repeat-row').dataset.editing='true'}
function sbRemoveRef(btn){btn.closest('.repeat-row').remove();sbRenumberRefs()}
function sbSaveRef(btn){let row=btn.closest('.repeat-row'),link=row.querySelector('[data-k="link"]'),note=row.querySelector('[data-k="note"]'),intent=row.querySelector('[data-k="intent"]');if(!link.value.trim()){link.focus();return}row.querySelector('[data-ref-link]').href=link.value.trim();row.querySelector('[data-ref-link]').textContent=(sbRefType(link.value)||'Abrir referência')+' ↗';row.querySelector('[data-ref-note]').textContent='“'+(note.value.trim()||'Sem observação')+'”';row.querySelector('[data-ref-intent]').textContent=sbIntentLabel(intent.value);row.dataset.editing='false';sbRenumberRefs()}
function sbRenumberRefs(){document.querySelectorAll('[data-sbrow="reference"] [data-ref-number]').forEach((x,i)=>x.textContent='REFERÊNCIA '+String(i+1).padStart(2,'0'))}
function sbToggleCoverage(){document.querySelectorAll('[data-coverage-target]').forEach(box=>{let input=document.querySelector(`[name="coverage_items"][value="${box.dataset.coverageTarget}"]`);box.hidden=!input?.checked})}
function sbToggleSchedule(){let yes=document.querySelector('[name="schedule_status"][value="yes"]')?.checked,box=document.querySelector('[data-schedule-details]');if(box)box.hidden=!yes}
function sbToggleHighlights(){let yes=document.querySelector('[name="highlights_choice"]')?.value==='yes',box=document.querySelector('[data-highlight-details]');if(box)box.hidden=!yes}

{
renderStoryPublic=function(x,token){let b=x.briefing||{},e=x.event||{},sched=sbObj(b.schedule_details),people=sbArr(b.important_people_items),refs=sbArr(b.reference_items),suppliers=sbArr(b.supplier_items),vibes=sbArr(b.vibe_styles),coverage=sbArr(b.coverage_items),date=e.starts_at?new Date(e.starts_at).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'}):'',names=sbNames(b,e);if(!coverage.length){if(b.getting_ready_bride)coverage.push('bride');if(b.first_look)coverage.push('first_look');coverage.push('ceremony','reception')}R.innerHTML=`<div class="story-public"><div class="wrap"><section class="hero"><small class="ey">COLAB · STORYMAKER</small><h1>${E(names)}</h1>${date?`<div class="event-date">${E(date)}</div>`:''}${e.location?`<div class="event-place">${E(e.location)}</div>`:''}<p class="intro">Preparamos esse espaço para conhecer alguns detalhes do grande dia de vocês, entender suas preferências e alinhar nossa cobertura.<br><br>Tudo que vocês contarem aqui vai ajudar a gente a chegar no evento sabendo o que merece atenção especial e o que realmente importa para vocês. 🧡</p></section><div class="brief-progress"><div class="brief-progress-top"><span id="briefProgressText">ETAPA 1 DE 9</span><span>DO JEITO DE VOCÊS</span></div><div class="brief-progress-track"><i id="briefProgress" style="width:11.1%"></i></div></div><form id="storyPublicForm">
<section class="block brief-step on"><small class="ey">1 · O GRANDE DIA</small><h2>O grande dia</h2><p>Só o que a gente precisa saber para chegar alinhada com o cronograma de vocês.</p><span class="brief-choice-title">O que faz parte da cobertura?</span><div class="choice-grid">${[['bride','Making of da noiva'],['first_look','First look'],['ceremony','Cerimônia'],['reception','Recepção / festa'],['other','Outro momento importante']].map(([v,l])=>`<label class="choice-pill"><input type="checkbox" name="coverage_items" value="${v}" ${coverage.includes(v)?'checked':''} onchange="sbToggleCoverage()"> ${l}</label>`).join('')}</div><div class="brief-conditional" data-coverage-target="bride" ${coverage.includes('bride')?'':'hidden'}><b>Making of da noiva</b><div class="brief-two"><input name="bride_time" value="${E(sched.bride_time||'')}" placeholder="Horário"><input name="bride_location" value="${E(sched.bride_location||sched.bride||'')}" placeholder="Local"></div></div><div class="brief-conditional" data-coverage-target="first_look" ${coverage.includes('first_look')?'':'hidden'}><b>First look</b><div class="brief-two"><input name="first_look_time" value="${E(sched.first_look_time||'')}" placeholder="Horário aproximado"><input name="first_look_location" value="${E(sched.first_look_location||'')}" placeholder="Local"></div><input name="first_look_note" value="${E(sched.first_look_note||'')}" placeholder="Observação opcional"></div><div class="brief-conditional" data-coverage-target="ceremony" ${coverage.includes('ceremony')?'':'hidden'}><b>Cerimônia</b><div class="brief-two"><input name="ceremony_time" value="${E(sched.ceremony_time||'')}" placeholder="Horário"><input name="ceremony_location_detail" value="${E(sched.ceremony_location||sched.ceremony||b.ceremony_location||e.location||'')}" placeholder="Local"></div></div><div class="brief-conditional" data-coverage-target="reception" ${coverage.includes('reception')?'':'hidden'}><b>Recepção / festa</b><div class="brief-two"><input name="reception_time" value="${E(sched.reception_time||'')}" placeholder="Horário"><input name="reception_location_detail" value="${E(sched.reception_location||sched.reception||b.reception_location||'')}" placeholder="Local"></div></div><div class="brief-conditional" data-coverage-target="other" ${coverage.includes('other')?'':'hidden'}><b>Outro momento importante</b><input name="coverage_other" value="${E(sched.coverage_other||'')}" placeholder="Conta pra gente qual momento"></div><div class="cerimonial-highlight" style="margin-top:16px"><small class="ey">NOSSO CONTATO NO GRANDE DIA</small><h3>Cerimonial / assessoria</h3><div class="brief-two"><input name="ceremonialist_name" value="${E(b.ceremonialist_name||'')}" placeholder="Nome / assessoria"><input name="ceremonialist_instagram" value="${E(b.ceremonialist_instagram||'')}" placeholder="@ Instagram"><input name="ceremonialist_whatsapp" value="${E(b.ceremonialist_whatsapp||'')}" placeholder="WhatsApp"></div></div><span class="brief-choice-title">Cronograma do dia</span><label>Já tem um cronograma do casamento?</label><div class="choice-grid">${sbRadio('schedule_status','yes','Sim',b.schedule_status)}${sbRadio('schedule_status','not_yet','Ainda não',b.schedule_status)}</div><div class="brief-conditional" data-schedule-details ${b.schedule_status==='yes'?'':'hidden'}><label>Link do cronograma</label><input name="schedule_url" type="url" value="${E(b.schedule_url||'')}" placeholder="Drive, PDF, foto ou documento"></div><label>Tem alguma mudança de local, intervalo ou detalhe que a gente precisa saber?</label><textarea name="schedule_notes">${E(b.schedule_notes||'')}</textarea><div class="brief-actions"><button type="button" class="btn pri" onclick="sbStep(1)">Continuar →</button></div></section>
<section class="block featured brief-step"><small class="ey">2 · PRIORIDADES</small><h2>O que vocês querem guardar desse dia? 🧡</h2><p>Marquem tudo que gostariam de conseguir assistir depois. Essas escolhas viram prioridades para a nossa equipe durante a cobertura.</p><label>O que vocês gostariam que aparecesse nos vídeos?</label><div class="choice-grid">${['Decoração e detalhes','Vestido, acessórios e preparação','Chegada dos convidados','Reação do noivo','Entrada da noiva','Família e pessoas importantes','Votos','Beijo','Saída da cerimônia','Recepção e ambiente','Comida, doces e buffet','Brinde','Pista de dança e festa','Momentos espontâneos','Trend com madrinhas ou padrinhos'].map(v=>`<label class="choice-pill"><input type="checkbox" name="desired_capture_items" value="${v}" ${sbArr(b.must_capture_items).includes(v)?'checked':''}> ${v}</label>`).join('')}</div><label>Tem algum momento que você já sabe que vai fazer questão de ver depois?</label><textarea name="must_moment" placeholder="Ex.: a entrada, os votos, o abraço com a avó...">${E(b.must_moment||'')}</textarea><label>Tem alguma reação que você quer muito que a gente registre?</label><textarea name="must_reaction" placeholder="Ex.: reação do noivo, dos pais ou de alguém especial...">${E(b.must_reaction||'')}</textarea><label>Tem algum detalhe, tradição ou momento específico que merece uma atenção especial?</label><textarea name="must_specific" placeholder="Pode contar tudo que não pode passar.">${E(b.must_specific||'')}</textarea><div class="brief-actions"><button type="button" class="btn ghost" onclick="sbStep(0)">Voltar</button><button type="button" class="btn pri" onclick="sbStep(2)">Continuar →</button></div></section>
<section class="block brief-step"><small class="ey">3 · PESSOAS IMPORTANTES</small><h2>Pessoas importantes para vocês</h2><p>Se tiver alguém que vocês gostariam que recebesse uma atenção especial da nossa equipe, contem pra gente.</p><div class="repeat-list" data-sblist="person">${sbRowsV2('person',people)}</div><button type="button" class="btn ghost small" onclick="sbAddRowV2('person')">＋ Adicionar pessoa importante</button><div class="brief-actions"><button type="button" class="btn ghost" onclick="sbStep(1)">Voltar</button><button type="button" class="btn pri" onclick="sbStep(3)">Continuar →</button></div></section>
<section class="block brief-step"><small class="ey">4 · REFERÊNCIAS</small><h2>Salvou algo e pensou “quero isso”? 👀</h2><p>Pode mandar pra gente. Assim conseguimos entender não só o vídeo que vocês gostaram, mas exatamente o que chamou atenção nele.</p><div class="repeat-list" data-sblist="reference">${sbRowsV2('reference',refs)}</div><button type="button" class="btn ghost small" onclick="sbAddRowV2('reference')">＋ Adicionar referência</button><div class="brief-actions"><button type="button" class="btn ghost" onclick="sbStep(2)">Voltar</button><button type="button" class="btn pri" onclick="sbStep(4)">Continuar →</button></div></section>
<section class="block brief-step"><small class="ey">5 · PREFERÊNCIAS</small><h2>A cara de vocês</h2><p>Conta pra gente o que combina — e também o que não combina — com vocês.</p><label>A cobertura de vocês combina mais com:</label><div class="choice-grid">${['Espontânea','Divertida','Emocionante','Romântica','Elegante','Festeira'].map(v=>`<label class="choice-pill"><input type="checkbox" name="vibe_styles" value="${v}" ${vibes.includes(v)?'checked':''}> ${v}</label>`).join('')}</div><label>Vocês gostam de aparecer falando nos Stories?</label><div class="choice-grid">${sbRadio('likes_talking','yes','Sim',b.likes_talking)}${sbRadio('likes_talking','not_much','Não muito',b.likes_talking)}${sbRadio('likes_talking','depends','Depende',b.likes_talking)}</div><label>Gostam de trends?</label><div class="choice-grid">${sbRadio('likes_trends','yes','Sim',b.likes_trends)}${sbRadio('likes_trends','some','Algumas',b.likes_trends)}${sbRadio('likes_trends','no','Não é muito a nossa cara',b.likes_trends)}</div><label>Vocês preferem:</label><div class="choice-grid">${sbRadio('direction_preference','spontaneous','Registros bem espontâneos',b.direction_preference)}${sbRadio('direction_preference','balanced','Espontâneo + algumas cenas dirigidas',b.direction_preference)}${sbRadio('direction_preference','directed','Gostamos quando a equipe orienta mais',b.direction_preference)}</div><label>A trilha dos vídeos combina mais com:</label><div class="choice-grid">${sbRadio('music_vibe','animated','Animada e festeira',b.music_vibe)}${sbRadio('music_vibe','romantic','Romântica',b.music_vibe)}${sbRadio('music_vibe','emotional','Emocionante',b.music_vibe)}${sbRadio('music_vibe','elegant','Elegante e leve',b.music_vibe)}${sbRadio('music_vibe','mixed','Uma mistura',b.music_vibe)}${sbRadio('music_vibe','open','Confiamos na escolha da Colab',b.music_vibe)}</div><label>Tem alguma música que vocês gostariam muito que aparecesse em algum conteúdo?</label><input name="music_important" value="${E(b.music_important||'')}" placeholder="Nome da música ou link · opcional"><label>Tem algum estilo de vídeo, trend ou jeito de gravar que não combina com vocês?</label><textarea name="style_avoid" placeholder="Ex.: não gostamos de vídeos muito posados ou de trends com dancinha...">${E(b.style_avoid||'')}</textarea><div class="brief-actions"><button type="button" class="btn ghost" onclick="sbStep(3)">Voltar</button><button type="button" class="btn pri" onclick="sbStep(5)">Continuar →</button></div></section>
<section class="block brief-step"><small class="ey">6 · STORIES</small><h2>Sobre os Stories</h2><label>Depois do evento, vocês querem salvar os Stories nos Destaques do Instagram?</label><select name="highlights_choice" onchange="sbToggleHighlights()"><option value="">Escolher</option><option value="yes" ${b.highlights_choice==='yes'?'selected':''}>Sim</option><option value="no" ${b.highlights_choice==='no'?'selected':''}>Não</option><option value="unsure" ${b.highlights_choice==='unsure'?'selected':''}>Ainda não sei</option></select><div class="brief-conditional" data-highlight-details ${b.highlights_choice==='yes'?'':'hidden'}><label>Vocês já têm um Destaque onde querem salvar?</label><div class="choice-grid">${sbRadio('highlight_has_existing','yes','Sim',b.highlight_has_existing)}${sbRadio('highlight_has_existing','no','Não',b.highlight_has_existing)}</div><label>Nome do Destaque, se já existir</label><input name="highlight_name" value="${E(b.highlight_name||'')}" placeholder="Opcional"><label>Se não existe, querem criar um novo?</label><div class="choice-grid">${sbRadio('highlight_create_new','yes','Sim',b.highlight_create_new)}${sbRadio('highlight_create_new','no','Não',b.highlight_create_new)}${sbRadio('highlight_create_new','unsure','Ainda não sabemos',b.highlight_create_new)}</div></div><label>Podemos marcar os fornecedores nos Stories?</label><div class="choice-grid">${sbRadio('mark_suppliers_choice','yes','Sim',b.mark_suppliers?'yes':'no')}${sbRadio('mark_suppliers_choice','no','Não',b.mark_suppliers?'yes':'no')}</div><label>Podemos repostar conteúdos em que vocês forem marcados?</label><div class="choice-grid">${sbRadio('repost_choice','yes','Sim',b.repost_permission?'yes':'no')}${sbRadio('repost_choice','no','Não',b.repost_permission?'yes':'no')}</div><div class="brief-actions"><button type="button" class="btn ghost" onclick="sbStep(4)">Voltar</button><button type="button" class="btn pri" onclick="sbStep(6)">Continuar →</button></div></section>
<section class="block brief-step"><small class="ey">7 · LIMITES</small><h2>Só pra deixar tudo alinhado</h2><label>A COLAB pode publicar registros desse casamento no nosso perfil?</label><div class="choice-grid">${sbRadio('publication_choice','yes','Sim',b.publication_choice||((b.publication_permission===true)?'yes':''))}${sbRadio('publication_choice','no','Não',b.publication_choice)}${sbRadio('publication_choice','talk','Prefiro conversar sobre isso',b.publication_choice)}</div><label>Existe alguma coisa que vocês não querem que seja filmada?</label><textarea name="do_not_capture" placeholder="Opcional">${E(b.do_not_capture||'')}</textarea><label>Existe alguma coisa que vocês não querem que seja publicada?</label><textarea name="do_not_publish" placeholder="Opcional">${E(b.do_not_publish||'')}</textarea><div class="brief-actions"><button type="button" class="btn ghost" onclick="sbStep(5)">Voltar</button><button type="button" class="btn pri" onclick="sbStep(7)">Continuar →</button></div></section>
<section class="block brief-step"><small class="ey">8 · FORNECEDORES</small><h2>Quem vai estar com a gente nesse dia?</h2><p>Esses @ ajudam bastante na hora dos Stories e das marcações.</p><div class="repeat-list" data-sblist="supplier">${sbRowsV2('supplier',suppliers)}</div><button type="button" class="btn ghost small" onclick="sbAddRowV2('supplier')">＋ Adicionar fornecedor</button><div class="brief-actions"><button type="button" class="btn ghost" onclick="sbStep(6)">Voltar</button><button type="button" class="btn pri" onclick="sbStep(8)">Continuar →</button></div></section>
<section class="block brief-step"><small class="ey">9 · ANTES DE TERMINAR</small><h2>Antes de terminar...</h2><label>Tem alguma coisa que a gente não perguntou e você acha importante sabermos?</label><textarea name="final_notes" placeholder="Esse campo é opcional.">${E(b.final_notes||'')}</textarea><div class="brief-note" style="margin-top:15px"><b>Falar diretamente com a Colab</b><br>Se houver algum momento, surpresa ou informação específica que prefiram compartilhar em particular, podem falar diretamente com a nossa equipe.</div><div class="brief-actions"><button type="button" class="btn ghost" onclick="sbStep(7)">Voltar</button><button class="btn pri">Enviar briefing 🧡</button></div></section></form></div></div>`;let form=document.getElementById('storyPublicForm');form.querySelectorAll('[name="schedule_status"]').forEach(i=>i.addEventListener('change',sbToggleSchedule));form.onsubmit=async ev=>{ev.preventDefault();let f=new FormData(form),data={};for(let[k,v]of f.entries())if(!['vibe_styles','coverage_items','desired_capture_items'].includes(k))data[k]=v;data.coverage_items=f.getAll('coverage_items');data.getting_ready_bride=data.coverage_items.includes('bride');data.getting_ready_groom=false;data.first_look=data.coverage_items.includes('first_look');data.mark_suppliers=f.get('mark_suppliers_choice')==='yes';data.repost_permission=f.get('repost_choice')==='yes';data.publication_permission=f.get('publication_choice')==='yes';data.vibe_styles=f.getAll('vibe_styles');data.schedule_details={bride_time:f.get('bride_time')||'',bride_location:f.get('bride_location')||'',first_look_time:f.get('first_look_time')||'',first_look_location:f.get('first_look_location')||'',first_look_note:f.get('first_look_note')||'',ceremony_time:f.get('ceremony_time')||'',ceremony_location:f.get('ceremony_location_detail')||'',reception_time:f.get('reception_time')||'',reception_location:f.get('reception_location_detail')||'',coverage_other:f.get('coverage_other')||''};data.must_capture_items=[...f.getAll('desired_capture_items'),f.get('must_moment'),f.get('must_reaction'),f.get('must_specific')].flatMap(v=>String(v||'').split(/\n+/)).map(v=>v.trim()).filter(Boolean);data.important_people_items=sbCollect(form,'person');data.reference_items=sbCollect(form,'reference');data.supplier_items=sbCollect(form,'supplier');let btn=form.querySelector('button:not([type="button"])'),old=btn.textContent;try{btn.disabled=true;btn.textContent='Enviando...';let r=await tf(B+'/rest/v1/rpc/storymaker_public_submit',{method:'POST',headers:{apikey:K,'Content-Type':'application/json'},body:JSON.stringify({p_token:token,p_data:data})});if(!r.ok)throw Error(await r.text());R.innerHTML=`<div class="story-public public-success"><div class="block"><small class="ey">BRIEFING RECEBIDO</small><h1>Agora é com a gente. 🧡</h1><p class="intro">Recebemos tudo.<br><br>Essas informações vão ajudar nossa equipe a preparar a cobertura de vocês com muito mais atenção aos detalhes.<br><br>Mais perto do grande dia, revisamos tudo por aqui para chegar alinhada com o que combinamos.</p><button class="btn ghost" onclick="storyPublicBoot('${token}')">Quero acrescentar algo</button></div></div>`}catch(err){alert('Não conseguimos enviar agora. '+err.message);btn.disabled=false;btn.textContent=old}}};sbRenumberRefs()};

storymakerDetailModal=function(id){let e=D.events.find(x=>x.id===id),b=(D.storyBriefings||[]).find(x=>x.event_id===id);if(!e||!b?.submitted_at)return _sbDetailBase(id);let checks=(D.storyChecklist||[]).filter(x=>x.event_id===id),del=(D.storyDeliverables||[]).filter(x=>x.event_id===id),rec=(D.receivables||[]).filter(x=>x.event_id===id),must=sbArr(b.must_capture_items),people=sbArr(b.important_people_items),refs=sbArr(b.reference_items),suppliers=sbArr(b.supplier_items),vibes=sbArr(b.vibe_styles),sched=sbObj(b.schedule_details),coverage=sbArr(b.coverage_items),pub=({yes:'Publicação autorizada',no:'Publicação não autorizada',talk:'Preferem conversar'})[b.publication_choice]||'Não informado';return`<div class="modalbg"><div class="modal wide"><div class="head"><div><small class="ey">STORYMAKER</small><h2>${E(e.title)}</h2><p class="muted">${fmtDate(String(e.starts_at||'').slice(0,10))}${e.location?' · '+E(e.location):''}</p></div><button class="btn ghost small" data-close>✕</button></div><section class="panel"><div class="head"><div><small class="ey">BRIEFING OPERACIONAL</small><h3>Recebido e organizado ✓</h3></div><button class="btn ghost small" onclick="copyStoryBriefing('${id}')">Copiar link</button></div><div class="story-op-grid"><div class="story-op-block"><h4>NÃO PODE PASSAR</h4>${must.length?`<ul>${must.map(x=>`<li>🔥 ${E(x)}</li>`).join('')}</ul>`:'<span class="muted">Nada informado.</span>'}</div><div class="story-op-block"><h4>PESSOAS IMPORTANTES</h4>${people.length?people.map(p=>`<div class="op-line"><b>${E(p.name)}</b><small>${E(p.relation||'Relação não informada')}</small></div>`).join(''):'<span class="muted">Ninguém informado.</span>'}</div><div class="story-op-block wide"><h4>REFERÊNCIAS</h4>${refs.length?refs.map((r,i)=>`<a class="story-ref-card" href="${E(r.link)}" target="_blank" rel="noopener"><b>${sbRefType(r.link)||'Referência'} ${String(i+1).padStart(2,'0')} ↗</b><small>“${E(r.note||'Sem observação')}” · ${E(sbIntentLabel(r.intent))}</small></a>`).join(''):'<span class="muted">Sem referências.</span>'}</div><div class="story-op-block"><h4>ESTILO / PREFERÊNCIAS</h4><div class="chips">${vibes.map(v=>`<span class="tag o">${E(v)}</span>`).join('')}</div><small>${E(({yes:'Gostam de falar nos Stories',not_much:'Não gostam muito de falar',depends:'Depende para falar'})[b.likes_talking]||'')}${b.likes_trends?' · '+E(({yes:'Gostam de trends',some:'Algumas trends',no:'Trends não combinam'})[b.likes_trends]||''):''}${b.music_important?' · Música: '+E(b.music_important):''}</small></div><div class="story-op-block"><h4>FORNECEDORES</h4>${suppliers.length?suppliers.map(s=>`<div class="op-line"><b>${E(s.category||'Fornecedor')}</b><small>${E(s.name||'')}${s.instagram?' · '+E(s.instagram):''}</small></div>`).join(''):'<span class="muted">Nenhum fornecedor.</span>'}</div><div class="story-op-block"><h4>STORIES / DESTAQUES</h4><p>${E(({yes:'Querem salvar nos Destaques',no:'Não querem salvar nos Destaques',unsure:'Ainda não decidiram'})[b.highlights_choice]||'Não informado')}</p><small>${b.highlight_name?'Destaque: '+E(b.highlight_name)+' · ':''}${b.mark_suppliers?'Marcar fornecedores':'Não marcar fornecedores'} · ${b.repost_permission?'Repost autorizado':'Repost não autorizado'}</small></div><div class="story-op-block"><h4>RESTRIÇÕES</h4><p><b>${E(pub)}</b></p><small>Não filmar: ${E(b.do_not_capture||'Nada informado.')}<br>Não publicar: ${E(b.do_not_publish||'Nada informado.')}</small></div><div class="story-op-block wide"><h4>CRONOGRAMA</h4><div class="op-line"><b>Cobertura</b><small>${E(coverage.map(v=>({bride:'Making of da noiva',first_look:'First look',ceremony:'Cerimônia',reception:'Recepção / festa',other:'Outro momento'})[v]||v).join(' · ')||'Não informada')}</small></div>${sched.bride_time||sched.bride_location?`<div class="op-line"><b>Making of da noiva</b><small>${E([sched.bride_time,sched.bride_location].filter(Boolean).join(' · '))}</small></div>`:''}${sched.first_look_time||sched.first_look_location?`<div class="op-line"><b>First look</b><small>${E([sched.first_look_time,sched.first_look_location,sched.first_look_note].filter(Boolean).join(' · '))}</small></div>`:''}${sched.ceremony_time||sched.ceremony_location?`<div class="op-line"><b>Cerimônia</b><small>${E([sched.ceremony_time,sched.ceremony_location].filter(Boolean).join(' · '))}</small></div>`:''}${sched.reception_time||sched.reception_location?`<div class="op-line"><b>Recepção / festa</b><small>${E([sched.reception_time,sched.reception_location].filter(Boolean).join(' · '))}</small></div>`:''}${b.schedule_url?`<a class="story-ref-card" href="${E(b.schedule_url)}" target="_blank" rel="noopener">Abrir cronograma ↗</a>`:''}</div></div></section><section class="panel confidential-box"><small class="ey">INFORMAÇÃO CONFIDENCIAL 🔒</small><h3>Somente equipe Colab</h3><form id="storyConfidentialForm" data-briefing="${b.id}" data-event="${id}"><textarea name="confidential_notes" rows="3" placeholder="Surpresas e informações que nunca aparecem no link público.">${E(b.confidential_notes||'')}</textarea><button class="btn ghost small" style="margin-top:8px">Salvar</button></form></section><section class="story-section"><div class="head"><div><small class="ey">CAPTAÇÃO</small><h3>Prioridades e checklist</h3></div><button class="btn ghost small" onclick="addStoryCheck('${id}')">＋ Item</button></div>${checks.map(x=>`<label class="story-line"><input type="checkbox" ${x.completed?'checked':''} onchange="toggleStoryCheck('${x.id}',this.checked)"><div class="grow"><b class="${x.priority==='urgent'||x.priority==='high'?'story-priority':''}">${E(x.title)}</b><small class="${x.source==='briefing'?'story-priority-label':''}">${x.source==='briefing'?'PRIORIDADE DOS NOIVOS 🧡':'Checklist da equipe'} · ${E(x.category)}</small></div></label>`).join('')||'<div class="empty">Sem itens.</div>'}</section><section class="story-section"><div class="head"><h3>Entregas</h3><button class="btn ghost small" onclick="addStoryDeliverable('${id}')">＋ Entrega</button></div>${del.map(x=>`<div class="story-line"><div class="grow"><b>${E(x.title)}${x.quantity?' · '+x.quantity+'x':''}</b><small>${x.status==='delivered'?'Entregue':'Pendente'}</small></div><button class="btn ${x.status==='delivered'?'ghost':'pri'} small" onclick="toggleStoryDeliverable('${x.id}','${x.status}')">${x.status==='delivered'?'Reabrir':'Marcar entregue'}</button></div>`).join('')||'<div class="empty">Sem entregas.</div>'}</section><section class="story-section"><small class="ey">ARQUIVOS / DRIVE</small><div class="story-delivery">${[['Material bruto',e.delivery_raw_url],['Vídeos editados',e.delivery_edited_url],['Fotos',e.delivery_photos_url],['Pasta completa',e.delivery_folder_url]].filter(x=>x[1]).map(([n,u])=>`<a href="${E(u)}" target="_blank"><b>${n}</b><br><small>Abrir Drive ↗</small></a>`).join('')||'<div><b>Nenhum link ainda</b></div>'}</div></section><section class="story-section"><small class="ey">FINANCEIRO</small>${rec.map(r=>`<div class="row"><div class="grow"><b>${money(r.amount)}</b><small>${E(r.description)}</small></div><span class="tag ${r.status==='paid'?'g':'y'}">${r.status==='paid'?'Pago':'Pendente'}</span></div>`).join('')||'<div class="empty">Nenhum recebimento vinculado.</div>'}</section></div></div>`};

async function sbSaveConfidential(ev){ev.preventDefault();let f=new FormData(ev.currentTarget);try{await patch('storymaker_briefings',ev.currentTarget.dataset.briefing,{confidential_notes:f.get('confidential_notes')||null,updated_at:new Date().toISOString()});await load();MD={type:'storymakerDetail',id:ev.currentTarget.dataset.event};render();toast('Informação confidencial salva 🔒')}catch(err){toast(err.message)}}
const _sbBindBase=bind;bind=function(){_sbBindBase();document.getElementById('storyConfidentialForm')?.addEventListener('submit',sbSaveConfidential)};

// ===== STORYMAKER PRICE + SIMPLIFIED EVENT FORM =====
productionPage=function(){let ev=(D.events||[]).filter(e=>['storymaker','recording','event'].includes(e.event_type)).filter(e=>!productionClient||e.client_id===productionClient);return`<div class="toolbar"><div><small class="ey">STORYMAKER</small><h2 style="margin:5px 0">Eventos & coberturas</h2><p class="muted">Briefing, captação, entregas e arquivos de cada evento em um só lugar.</p></div><button class="btn pri" data-m="storyEventNew">＋ Novo evento</button></div><div class="filters"><select id="productionClient"><option value="">Todos</option>${D.clients.filter(c=>c.active).map(c=>`<option value="${c.id}" ${productionClient===c.id?'selected':''}>${E(c.name)}</option>`).join('')}</select></div><div class="story-grid">${ev.map(e=>{let b=(D.storyBriefings||[]).find(x=>x.event_id===e.id),checks=(D.storyChecklist||[]).filter(x=>x.event_id===e.id),del=(D.storyDeliverables||[]).filter(x=>x.event_id===e.id),done=checks.filter(x=>x.completed).length,delDone=del.filter(x=>x.status==='delivered').length,rec=(D.receivables||[]).filter(x=>x.event_id===e.id&&x.status==='pending').reduce((s,x)=>s+Number(x.amount||0),0),price=Number(e.extra_amount||0);return`<section class="panel story-card"><div class="head"><div><small class="ey">${E(lab(e.event_type))}</small><h3>${E(e.title)}</h3><p class="muted">${E(cl(e.client_id)?.name||'Evento avulso')} · ${fmtDate(String(e.starts_at||'').slice(0,10))}</p></div><button class="btn ghost small" onclick="openStoryEvent('${e.id}')">Abrir</button></div><div class="story-meta"><span class="tag ${b?.submitted_at?'g':'y'}">${b?.submitted_at?'Briefing recebido':'Briefing pendente'}</span><span class="tag">${e.location?E(e.location):'Local a definir'}</span>${e.is_extra&&rec>0?`<span class="tag g">Cobrança no Financeiro</span>`:''}</div><div class="story-progress"><div><small>CAPTAÇÃO</small><b>${done}/${checks.length}</b></div><div><small>ENTREGAS</small><b>${delDone}/${del.length}</b></div><div><small>VALOR DO EVENTO</small><b>${money(price)}</b></div></div></section>`}).join('')||'<div class="empty">Nenhum evento StoryMaker cadastrado.</div>'}</div>`};

eventEditModal=function(){let e=D.events.find(x=>x.id===MD.id);if(!e)return'';let types=[['storymaker','StoryMaker'],['recording','Captação'],['meeting','Reunião'],['event','Evento'],['other','Outro']],statuses=[['planned','Planejado'],['confirmed','Confirmado'],['completed','Concluído'],['cancelled','Cancelado']];return`<div class="modalbg"><div class="modal wide"><div class="head"><div><small class="ey">STORYMAKER / EVENTO</small><h2>${E(e.title)}</h2><p class="muted">Edite o evento, o valor e os materiais da entrega.</p></div><button class="btn ghost small" data-close>✕</button></div><form id="eventEditForm" data-event="${e.id}"><div class="formgrid"><div class="field"><label>Cliente</label><select name="client_id"><option value="" ${!e.client_id?'selected':''}>Sem cliente</option>${D.clients.map(c=>`<option value="${c.id}" ${e.client_id===c.id?'selected':''}>${E(c.name)}</option>`).join('')}</select></div><div class="field"><label>Tipo</label><select name="event_type">${types.map(([v,l])=>`<option value="${v}" ${e.event_type===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="field"><label>Nome do evento / casal</label><input name="title" value="${E(e.title)}" required></div><div class="formgrid"><div class="field"><label>Início</label><input name="starts_at" type="datetime-local" value="${dtInput(e.starts_at)}"></div><div class="field"><label>Fim</label><input name="ends_at" type="datetime-local" value="${dtInput(e.ends_at)}"></div></div><div class="formgrid"><div class="field"><label>Horas contratadas</label><input name="contracted_hours" type="number" step="0.5" min="0" value="${e.contracted_hours??''}"></div><div class="field"><label>Responsável</label><select name="assigned_to"><option value="">Equipe</option>${(D.profiles||[]).map(p=>`<option value="${p.user_id}" ${e.assigned_to===p.user_id?'selected':''}>${E(p.display_name)}</option>`).join('')}</select></div></div><div class="formgrid"><div class="field"><label>Status</label><select name="status">${statuses.map(([v,l])=>`<option value="${v}" ${e.status===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Local</label><input name="location" value="${E(e.location||'')}"></div></div><section class="panel" style="margin:14px 0;border-color:#693617"><small class="ey">VALOR & COBRANÇA</small><h3>Valor do evento</h3><div class="formgrid"><div class="field"><label>Valor</label><input name="extra_amount" type="number" step="0.01" min="0" inputmode="decimal" value="${Number(e.extra_amount||0)||''}" placeholder="0,00"></div><div class="field"><label>Vencimento <span class="muted">(opcional)</span></label><input name="extra_due_date" type="date" value="${e.extra_due_date||''}"></div></div><div class="field"><label><input name="is_extra" type="checkbox" ${e.is_extra?'checked':''}> Lançar este valor no Financeiro</label><small class="muted">Desmarque somente se o evento já estiver incluído em um Plano Ativo.</small></div></section><section class="panel" style="margin:14px 0"><small class="ey">ENTREGA / DRIVE</small><h3>Materiais do StoryMaker</h3><div class="field"><label>Status da entrega</label><select name="delivery_status"><option value="pending" ${(e.delivery_status||'pending')==='pending'?'selected':''}>Aguardando entrega</option><option value="organizing" ${e.delivery_status==='organizing'?'selected':''}>Organizando material</option><option value="delivered" ${e.delivery_status==='delivered'?'selected':''}>Entrega concluída</option></select></div><div class="formgrid"><div class="field"><label>Material bruto</label><input name="delivery_raw_url" type="url" value="${E(e.delivery_raw_url||'')}" placeholder="Link do Drive"></div><div class="field"><label>Vídeos editados</label><input name="delivery_edited_url" type="url" value="${E(e.delivery_edited_url||'')}" placeholder="Link do Drive"></div></div><div class="formgrid"><div class="field"><label>Fotos</label><input name="delivery_photos_url" type="url" value="${E(e.delivery_photos_url||'')}" placeholder="Link do Drive"></div><div class="field"><label>Pasta completa</label><input name="delivery_folder_url" type="url" value="${E(e.delivery_folder_url||'')}" placeholder="Link do Drive"></div></div></section><div class="field"><label>Observações</label><textarea name="notes" rows="3">${E(e.notes||'')}</textarea></div><div class="actions"><button type="button" class="btn danger" data-eventdelete="${e.id}">Excluir evento</button><button class="btn pri">Salvar alterações</button></div></form></div></div>`};

