saveEventEdit=async function(ev){ev.preventDefault();let f=new FormData(ev.currentTarget),id=ev.currentTarget.dataset.event;try{await patch('events',id,{client_id:f.get('client_id')||null,title:f.get('title'),event_type:f.get('event_type'),starts_at:f.get('starts_at')?new Date(f.get('starts_at')).toISOString():null,ends_at:f.get('ends_at')?new Date(f.get('ends_at')).toISOString():null,contracted_hours:f.get('contracted_hours')||null,assigned_to:f.get('assigned_to')||null,location:f.get('location')||null,is_extra:f.get('is_extra')==='on',extra_amount:f.get('extra_amount')||null,extra_due_date:f.get('extra_due_date')||null,payment_method:f.get('payment_method')||null,payment_terms:f.get('payment_terms')||'full',deposit_amount:f.get('deposit_amount')||null,deposit_due_date:f.get('deposit_due_date')||null,balance_due_date:f.get('balance_due_date')||null,delivery_status:f.get('delivery_status')||'pending',delivery_raw_url:f.get('delivery_raw_url')||null,delivery_edited_url:f.get('delivery_edited_url')||null,delivery_photos_url:f.get('delivery_photos_url')||null,delivery_folder_url:f.get('delivery_folder_url')||null,script_text:null,script_notes:null,script_visible_to_client:false,notes:f.get('notes')||null,status:f.get('status'),updated_at:new Date().toISOString()});MD=null;await load();render();toast('Evento, pagamento e entrega atualizados')}catch(x){toast(x.message)}};

clientStorymakerPage=function(){let evs=D.events.filter(e=>['storymaker','recording','event'].includes(e.event_type)).slice().sort((a,b)=>String(b.starts_at||'').localeCompare(String(a.starts_at||'')));return`<section class="hero module-hero"><div><small class="ey">STORYMAKER</small><h2>Seus eventos e entregas.</h2><p class="muted">Acesse os materiais de cada cobertura sem procurar links no WhatsApp.</p></div></section>${evs.map(e=>{let ds=e.delivery_status||'pending',label=ds==='delivered'?'Entrega concluída ✓':ds==='organizing'?'Organizando material':'Aguardando entrega',links=[];if(e.delivery_raw_url)links.push(`<a class="delivery-link" href="${E(e.delivery_raw_url)}" target="_blank" rel="noopener"><span>🎬 Material bruto</span><b>↗</b></a>`);if(e.delivery_edited_url)links.push(`<a class="delivery-link" href="${E(e.delivery_edited_url)}" target="_blank" rel="noopener"><span>✨ Vídeos editados</span><b>↗</b></a>`);if(e.delivery_photos_url)links.push(`<a class="delivery-link" href="${E(e.delivery_photos_url)}" target="_blank" rel="noopener"><span>📸 Fotos</span><b>↗</b></a>`);if(e.delivery_folder_url)links.push(`<a class="delivery-link" href="${E(e.delivery_folder_url)}" target="_blank" rel="noopener"><span>📁 Entrega completa</span><b>↗</b></a>`);return`<article class="panel delivery-panel"><div class="head"><div><small class="ey">${E(lab(e.event_type))}</small><h3>${E(e.title)}</h3><p class="muted">${fmtDate(String(e.starts_at||'').slice(0,10))}${e.starts_at?' · '+fmtTime(e.starts_at):''}</p></div><span class="tag delivery-status ${ds}">${label}</span></div>${links.length?`<div class="delivery-grid">${links.join('')}</div>`:'<div class="empty">Os links da entrega aparecerão aqui assim que o material estiver organizado.</div>'}</article>`}).join('')||'<div class="panel empty">Nenhum evento de StoryMaker cadastrado ainda.</div>'}`};

const _storyDirectionDetailBase=storymakerDetailModal;
storymakerDetailModal=function(id){let html=_storyDirectionDetailBase(id),b=(D.storyBriefings||[]).find(x=>x.event_id===id);if(!b?.submitted_at)return html;let music=({animated:'Animada e festeira',romantic:'Romântica',emotional:'Emocionante',elegant:'Elegante e leve',mixed:'Uma mistura',open:'Confiam na escolha da Colab'})[b.music_vibe]||b.music_vibe||'Não informada',block=`<div class="story-op-block"><h4>DIREÇÃO CRIATIVA</h4><p><b>Trilha:</b> ${E(music)}</p>${b.music_important?`<small>Música indicada: ${E(b.music_important)}</small>`:''}${b.style_avoid?`<p class="muted" style="margin-top:8px"><b>Não combina com eles:</b> ${E(b.style_avoid)}</p>`:''}</div>`;return html.replace('<div class="story-op-block"><h4>FORNECEDORES</h4>',block+'<div class="story-op-block"><h4>FORNECEDORES</h4>')};

