const contractStyle=document.createElement('style');contractStyle.textContent=`.contract-panel{border-color:#4a2a18!important;background:linear-gradient(145deg,#17120f,#111)}.contract-status{display:inline-flex;margin:6px 0 12px}.contract-files{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:10px 0}.contract-file{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px;border:1px solid #333;border-radius:12px;background:#101010}.contract-file small{display:block;color:#777;margin-top:3px}.contract-public{border-color:#6d3517!important;background:linear-gradient(145deg,#21140d,#131313)!important}.contract-public .contract-steps{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin:13px 0}.contract-public .contract-steps span{padding:9px;border:1px solid #3b2a20;border-radius:11px;text-align:center;font-size:10px;font-weight:800}.contract-upload-name{display:block;margin-top:8px;color:#ff9b5e}@media(max-width:680px){.contract-files,.contract-public .contract-steps{grid-template-columns:1fr}}`;document.head.appendChild(contractStyle);

const _contractEventEditBase=eventEditModal;
eventEditModal=function(){let html=_contractEventEditBase(),e=D.events.find(x=>x.id===MD.id);if(!e||!html)return html;let status=e.contract_status==='signed'?'Contrato assinado ✓':e.contract_storage_path?'Aguardando assinatura':'Contrato ainda não enviado',files=`<div class="contract-files">${e.contract_storage_path?`<div class="contract-file"><div><b>Contrato para assinatura</b><small>${E(e.contract_file_name||'Contrato')}</small></div><button type="button" class="btn ghost small" onclick="openFile('${E(e.contract_storage_path)}')">Abrir ↗</button></div>`:''}${e.signed_contract_storage_path?`<div class="contract-file"><div><b>Contrato assinado</b><small>${E(e.signed_contract_file_name||'Arquivo devolvido')}</small></div><button type="button" class="btn pri small" onclick="openFile('${E(e.signed_contract_storage_path)}')">Abrir ↗</button></div>`:''}</div>`,panel=`<section class="panel contract-panel" style="margin:14px 0"><small class="ey">CONTRATO</small><h3>Contrato do evento</h3><span class="tag ${e.contract_status==='signed'?'g':e.contract_storage_path?'y':''} contract-status">${status}</span>${files}<div class="drop"><label for="eventContractFile" class="btn ${e.contract_storage_path?'ghost':'pri'}">${e.contract_storage_path?'Substituir contrato':'＋ Enviar contrato'}</label><input id="eventContractFile" name="contract_file" type="file" accept=".pdf,.doc,.docx,image/jpeg,image/png,image/webp"><p>O documento aparecerá no link privado do casal para baixar, assinar e devolver.</p></div></section>`;return html.replace('<section class="panel" style="margin:14px 0"><small class="ey">ENTREGA / DRIVE</small>',panel+'<section class="panel" style="margin:14px 0"><small class="ey">ENTREGA / DRIVE</small>')};

const _contractSaveEventEditBase=saveEventEdit;
saveEventEdit=async function(ev){let form=ev.currentTarget,file=form.querySelector('[name="contract_file"]')?.files?.[0],id=form.dataset.event;if(file){ev.preventDefault();try{if(file.size>15*1024*1024)throw Error('Escolha um contrato de até 15 MB.');let allowed=['application/pdf','image/jpeg','image/png','image/webp','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document'];if(!allowed.includes(file.type))throw Error('Envie o contrato em PDF, Word ou imagem.');let name=Date.now()+'-'+file.name.replace(/[^a-zA-Z0-9._-]/g,'-'),path=`${M.organization_id}/events/${id}/contracts/original/${name}`;await uploadRaw(file,path);await patch('events',id,{contract_storage_path:path,contract_file_name:file.name,contract_uploaded_at:new Date().toISOString(),contract_status:'pending_signature',signed_contract_storage_path:null,signed_contract_file_name:null,signed_contract_uploaded_at:null,updated_at:new Date().toISOString()})}catch(x){return toast(x.message)}}return _contractSaveEventEditBase(ev)};

const _contractDetailBase=storymakerDetailModal;
storymakerDetailModal=function(id){let html=_contractDetailBase(id),e=D.events.find(x=>x.id===id);if(!e)return html;let status=e.contract_status==='signed'?'Assinado e recebido ✓':e.contract_storage_path?'Aguardando assinatura':'Não enviado',block=`<section class="story-section"><div class="head"><div><small class="ey">CONTRATO</small><h3>${status}</h3></div>${e.contract_storage_path?`<button class="btn ghost small" onclick="openFile('${E(e.contract_storage_path)}')">Ver contrato</button>`:''}</div>${e.signed_contract_storage_path?`<div class="contract-file"><div><b>Documento assinado</b><small>${E(e.signed_contract_file_name||'Contrato devolvido')}${e.signed_contract_uploaded_at?' · '+notificationWhen(e.signed_contract_uploaded_at):''}</small></div><button class="btn pri small" onclick="openFile('${E(e.signed_contract_storage_path)}')">Abrir ↗</button></div>`:'<p class="muted">Assim que o casal devolver o arquivo assinado, ele aparecerá aqui.</p>'}</section>`;return html.replace('<section class="story-section"><small class="ey">FINANCEIRO</small>',block+'<section class="story-section"><small class="ey">FINANCEIRO</small>')};

async function loadStoryContractPublic(token){let host=document.getElementById('storyContractPublic');if(!host)return;try{let r=await tf(B+'/functions/v1/story-contract',{method:'POST',headers:{apikey:K,'Content-Type':'application/json'},body:JSON.stringify({token})});let x=await r.json();if(!r.ok)throw Error(x.error||'Não conseguimos abrir o contrato.');if(!x.available){host.remove();return}let signed=x.status==='signed';host.innerHTML=`<small class="ey">CONTRATO DO EVENTO</small><h2>${signed?'Contrato recebido ✓':'Contrato para assinatura'}</h2><p>${signed?'O documento assinado já está com a equipe Colab. Se precisarem corrigir alguma coisa, vocês podem enviar uma nova versão por aqui.':'Baixem o documento, façam a assinatura e depois devolvam o arquivo assinado neste mesmo espaço.'}</p><div class="contract-steps"><span>1 · Abrir contrato</span><span>2 · Assinar</span><span>3 · Devolver aqui</span></div><div class="actions"><a class="btn ghost" href="${E(x.contractUrl||'#')}" target="_blank" rel="noopener">Abrir contrato ↗</a><label for="storySignedContract" class="btn pri">${signed?'Enviar nova versão':'Anexar contrato assinado'}</label></div><input id="storySignedContract" type="file" hidden accept=".pdf,.doc,.docx,image/jpeg,image/png,image/webp" onchange="storyContractFilePicked(this)"><small id="storyContractFileName" class="contract-upload-name">PDF, Word ou foto · até 15 MB</small><button type="button" id="storyContractSend" class="btn pri full" style="margin-top:10px;display:none" onclick="uploadStorySignedContract('${token}')">Enviar contrato assinado</button>`}catch(err){host.innerHTML=`<small class="ey">CONTRATO</small><p class="muted">${E(err.message)}</p>`}}
function storyContractFilePicked(input){let file=input.files?.[0],name=document.getElementById('storyContractFileName'),btn=document.getElementById('storyContractSend');if(name)name.textContent=file?file.name:'PDF, Word ou foto · até 15 MB';if(btn)btn.style.display=file?'block':'none'}
async function uploadStorySignedContract(token){let input=document.getElementById('storySignedContract'),file=input?.files?.[0],btn=document.getElementById('storyContractSend');if(!file)return;if(file.size>15*1024*1024)return alert('Escolha um arquivo de até 15 MB.');let fd=new FormData();fd.append('token',token);fd.append('file',file);try{btn.disabled=true;btn.textContent='Enviando...';let r=await tf(B+'/functions/v1/story-contract',{method:'POST',headers:{apikey:K},body:fd},300000),x=await r.json();if(!r.ok)throw Error(x.error||'Não conseguimos enviar.');await loadStoryContractPublic(token)}catch(err){alert(err.message);btn.disabled=false;btn.textContent='Enviar contrato assinado'}}

const _contractPublicRenderBase=renderStoryPublic;
renderStoryPublic=function(x,token){_contractPublicRenderBase(x,token);let hero=document.querySelector('.story-public .hero');if(!hero)return;let host=document.createElement('section');host.id='storyContractPublic';host.className='block contract-public';host.innerHTML='<small class="ey">CONTRATO</small><p class="muted">Carregando documento...</p>';hero.insertAdjacentElement('afterend',host);loadStoryContractPublic(token)};

const _storyBootBase=boot;
boot=async function(){let token=new URLSearchParams(location.search).get('story');if(token)return storyPublicBoot(token);return _storyBootBase()};

