function sbEventFact(label,value,kind){let box=document.createElement('div');box.className='event-fact '+(kind||'');let small=document.createElement('small'),strong=document.createElement('strong');small.textContent=label;strong.textContent=value;box.append(small,strong);return box}
function sbSyncSupplierStep(){let form=document.getElementById('storyPublicForm'),box=form?.querySelector('[data-supplier-marking-box]'),note=form?.querySelector('[data-supplier-marking-note]');if(!box||!note)return;let allowed=form.querySelector('[name="mark_suppliers_choice"]:checked')?.value==='yes';box.hidden=!allowed;note.hidden=allowed}

