sbStep=function(n){let steps=[...document.querySelectorAll('.brief-step')],max=steps.length-1;n=Math.max(0,Math.min(max,n));steps.forEach((x,i)=>x.classList.toggle('on',i===n));let bar=document.getElementById('briefProgress'),txt=document.getElementById('briefProgressText');if(bar)bar.style.width=((n+1)/steps.length*100)+'%';if(txt)txt.textContent=`ETAPA ${n+1} DE ${steps.length}`;sbSyncSupplierStep();let target=document.querySelector('.brief-progress');if(target)target.scrollIntoView({behavior:'smooth',block:'start'})};

function refineStoryPublicExperience(x){let hero=document.querySelector('.story-public .hero');if(!hero)return;let intro=hero.querySelector('.intro'),date=hero.querySelector('.event-date'),place=hero.querySelector('.event-place');if(intro)intro.textContent='Contem pra gente o que merece atenção especial. Isso ajuda a Colab a chegar alinhada e preparar uma cobertura com a cara de vocês. 🧡';if(date||place){let facts=document.createElement('div');facts.className='event-facts';if(date){facts.appendChild(sbEventFact('DATA DO CASAMENTO',date.textContent,'date'));date.remove()}if(place){facts.appendChild(sbEventFact('ONDE VAI SER',place.textContent,'place'));place.remove()}hero.insertBefore(facts,intro||null)}

let captureInput=document.querySelector('[name="desired_capture_items"]');if(captureInput){let step=captureInput.closest('.brief-step'),grid=captureInput.closest('.choice-grid');if(grid){let label=grid.previousElementSibling;if(label?.tagName==='LABEL')label.remove();grid.remove()}let title=step.querySelector('h2'),desc=step.querySelector('h2+p');if(title)title.textContent='O que não pode passar 🧡';if(desc)desc.textContent='O básico do casamento a gente já sabe que precisa registrar. Aqui, contem só o que é específico de vocês.';let fields=[['must_moment','Existe algum momento específico, fora do que normalmente acontece, que vocês fazem questão de ter gravado?','Ex.: uma homenagem, um encontro especial, uma tradição da família...'],['must_reaction','Tem alguma reação específica que vocês querem muito que a gente registre?','Ex.: a reação da avó, dos pais ou de uma pessoa especial...'],['must_specific','Tem algum detalhe com significado especial que a gente precisa reconhecer?','Ex.: um objeto de família, uma homenagem na decoração ou algo preparado por alguém...']];fields.forEach(([name,labelText,placeholder])=>{let field=step.querySelector(`[name="${name}"]`);if(!field)return;field.placeholder=placeholder;let label=field.previousElementSibling;if(label?.tagName==='LABEL')label.textContent=labelText})}

let talk=document.querySelector('[name="publication_choice"][value="talk"]');if(talk)talk.closest('label')?.remove();let mark=document.querySelector('[name="mark_suppliers_choice"]');if(mark){let label=mark.closest('.choice-grid')?.previousElementSibling;if(label?.tagName==='LABEL')label.textContent='Vocês querem que a gente marque fornecedores nos Stories?';document.querySelectorAll('[name="mark_suppliers_choice"]').forEach(i=>i.addEventListener('change',sbSyncSupplierStep))}

let supplierList=document.querySelector('[data-sblist="supplier"]');if(supplierList){let step=supplierList.closest('.brief-step'),add=supplierList.nextElementSibling,title=step.querySelector('h2'),desc=step.querySelector('h2+p'),hasSaved=sbArr(x?.briefing?.supplier_items).length>0;if(title)title.textContent='Marcações do dia';if(desc)desc.textContent='Só precisa adicionar quem realmente precisa ser marcado ou mencionado. Não é necessário cadastrar todos os fornecedores.';if(!hasSaved)supplierList.innerHTML='';let box=document.createElement('div');box.className='supplier-marking-box';box.dataset.supplierMarkingBox='';supplierList.before(box);box.appendChild(supplierList);if(add?.tagName==='BUTTON')box.appendChild(add);let note=document.createElement('div');note.className='supplier-marking-note';note.dataset.supplierMarkingNote='';note.textContent='Certo. Como vocês não querem marcações, não precisam preencher nenhum fornecedor.';box.after(note);sbSyncSupplierStep()}}

