function sbPartnershipActionLabel(v){return({capture:'Captação específica',mark:'Marcar nos Stories',publish:'Publicar conteúdo',deliver:'Enviar o material'})[v]||v}
function sbPartnershipRows(rows){return rows.map(r=>{let chosen=String(r.actions||'').split(',').filter(Boolean);if(!chosen.length)chosen=['capture'];return`<div class="repeat-row partnership-row" data-sbrow="supplier"><input type="hidden" data-k="kind" value="partnership"><input type="hidden" data-k="category" value="Parceria / Permuta"><div class="brief-two"><input data-k="name" value="${E(r.name||'')}" placeholder="Fornecedor / parceiro"><input data-k="instagram" value="${E(r.instagram||'')}" placeholder="@ Instagram"></div><label>O que precisa aparecer na cobertura?</label><textarea data-k="capture" placeholder="Ex.: mostrar a decoração, registrar o produto ou fazer um vídeo específico...">${E(r.capture||'')}</textarea><label>O que foi combinado com essa parceria?</label><div class="choice-grid partnership-actions">${[['capture','Captação específica'],['mark','Marcar nos Stories'],['publish','Publicar conteúdo'],['deliver','Enviar o material']].map(([v,l])=>`<label class="choice-pill"><input type="checkbox" data-partnership-action value="${v}" ${chosen.includes(v)?'checked':''} onchange="sbSyncPartnershipActions(this.closest('[data-sbrow]'))"> ${l}</label>`).join('')}</div><input type="hidden" data-k="actions" value="${E(chosen.join(','))}"><label>Alguma orientação importante?</label><input data-k="notes" value="${E(r.notes||'')}" placeholder="Opcional"><button type="button" class="btn ghost small remove-row" onclick="this.closest('[data-sbrow]').remove()">Remover parceria</button></div>`}).join('')}
function sbSyncPartnershipActions(row){let hidden=row?.querySelector('[data-k="actions"]');if(hidden)hidden.value=[...row.querySelectorAll('[data-partnership-action]:checked')].map(i=>i.value).join(',')}
function sbAddPartnership(){let list=document.querySelector('[data-partnership-list]');if(list)list.insertAdjacentHTML('beforeend',sbPartnershipRows([{}]))}
function sbTogglePartnershipBox(){let form=document.getElementById('storyPublicForm'),yes=form?.querySelector('[name="has_partnership_capture"]:checked')?.value==='yes',box=form?.querySelector('[data-partnership-box]');if(!box)return;box.hidden=!yes;if(yes&&!box.querySelector('[data-sbrow="supplier"]'))sbAddPartnership()}

