sbCollect=function(form,kind){if(kind!=='supplier')return _sbCollectPartnershipBase(form,kind);let allowSuppliers=form.querySelector('[name="mark_suppliers_choice"]:checked')?.value==='yes',allowPartnerships=form.querySelector('[name="has_partnership_capture"]:checked')?.value==='yes';return[...form.querySelectorAll('[data-sbrow="supplier"]')].map(row=>{let o={};row.querySelectorAll('[data-k]').forEach(i=>o[i.dataset.k]=String(i.value||'').trim());return o}).filter(o=>o.kind==='partnership'?Boolean(o.name||o.instagram||o.capture||o.notes):Object.values(o).some(Boolean)).filter(o=>o.kind==='partnership'?allowPartnerships:allowSuppliers)};

function refineStoryPartnerships(x){let form=document.getElementById('storyPublicForm'),list=form?.querySelector('[data-sblist="supplier"]');if(!form||!list)return;let all=sbArr(x?.briefing?.supplier_items),partnerships=all.filter(s=>s?.kind==='partnership'),regular=all.filter(s=>s?.kind!=='partnership');list.innerHTML=regular.length?sbRowsV2('supplier',regular):'';let step=list.closest('.brief-step'),title=step?.querySelector('h2'),desc=step?.querySelector('h2+p');if(title)title.textContent='Marcações e parcerias';if(desc)desc.textContent='Só precisa preencher o que realmente exige uma marcação, uma postagem ou uma captação específica.';let mark=form.querySelector('[name="mark_suppliers_choice"]');if(mark){let label=mark.closest('.choice-grid')?.previousElementSibling;if(label?.tagName==='LABEL')label.textContent='Querem que a gente marque outros fornecedores nos Stories?'}let section=document.createElement('section');section.className='partnership-public';section.innerHTML=`<small class="ey">PARCERIA / PERMUTA</small><h3>Existe alguma parceria que exige uma captação específica?</h3><p>Por exemplo: mostrar a decoração, registrar um produto, marcar um perfil, publicar ou entregar algum material combinado.</p><div class="choice-grid">${sbRadio('has_partnership_capture','yes','Sim',partnerships.length?'yes':'no')}${sbRadio('has_partnership_capture','no','Não',partnerships.length?'yes':'no')}</div><div class="partnership-box" data-partnership-box ${partnerships.length?'':'hidden'}><div class="repeat-list" data-partnership-list>${sbPartnershipRows(partnerships)}</div><button type="button" class="btn ghost small" onclick="sbAddPartnership()">＋ Adicionar outra parceria</button><div class="brief-note" style="margin-top:10px">O que for combinado aqui vira prioridade no checklist da equipe. 🧡</div></div>`;step.querySelector('.brief-actions')?.before(section);form.querySelectorAll('[name="has_partnership_capture"]').forEach(i=>i.addEventListener('change',sbTogglePartnershipBox));sbTogglePartnershipBox()}

