const _storyPartnershipDetailBase=storymakerDetailModal;
storymakerDetailModal=function(id){let b=(D.storyBriefings||[]).find(x=>x.event_id===id),all=sbArr(b?.supplier_items),partnerships=all.filter(s=>s?.kind==='partnership'),regular=all.filter(s=>s?.kind!=='partnership'),original=b?.supplier_items,html;if(b)b.supplier_items=regular;try{html=_storyPartnershipDetailBase(id)}finally{if(b)b.supplier_items=original}if(!partnerships.length)return html;let cards=partnerships.map(p=>{let actions=String(p.actions||'').split(',').filter(Boolean);return`<div class="partnership-card"><b>${E(p.name||'Parceria')}</b>${p.instagram?`<small>${E(p.instagram)}</small>`:''}<p>${E(p.capture||'Captação específica não detalhada.')}</p>${actions.length?`<div class="chips">${actions.map(a=>`<span class="tag o">${E(sbPartnershipActionLabel(a))}</span>`).join('')}</div>`:''}${p.notes?`<small>${E(p.notes)}</small>`:''}</div>`}).join(''),block=`<div class="story-op-block wide"><h4>PARCERIAS / CAPTAÇÕES EXTRAS</h4>${cards}</div>`;return html.replace('<div class="story-op-block"><h4>FORNECEDORES</h4>',block+'<div class="story-op-block"><h4>FORNECEDORES</h4>')};


