storymakerDetailModal=function(id){let html=_storyRecognitionDetailBase(id),b=(D.storyBriefings||[]).find(x=>x.event_id===id),people=sbArr(b?.important_people_items).filter(p=>String(p.photo_path||'').includes('/briefing/people/'));if(!html||!people.length)return html;let block=`<div class="story-op-block wide"><h4>FOTOS PARA RECONHECIMENTO</h4><div class="recognition-grid">${people.map(p=>`<div class="recognition-card"><div><b>${E(p.name||'Pessoa importante')}</b><small>${E(p.relation||'Relação não informada')}</small></div><button class="btn ghost small" onclick="openFile('${E(p.photo_path)}')">Ver foto ↗</button></div>`).join('')}</div></div>`,needle='<div class="story-op-block wide"><h4>REFERÊNCIAS</h4>';return html.replace(needle,block+needle)};

const _storyBriefingPolishRenderBase=renderStoryPublic;
renderStoryPublic=function(x,token){storyBriefingPublicToken=token;let b=x?.briefing,all=sbArr(b?.reference_items),trend=all.find(r=>r?.source==='trend'),original=b?.reference_items;if(b)b.reference_items=all.filter(r=>r?.source!=='trend');try{_storyBriefingPolishRenderBase(x,token)}finally{if(b)b.reference_items=original}sbPrepareTrendField(trend);sbPolishSupplierLanguage();sbLoadPersonPhotos()};


