function sbAddVisualIdentityV419(x){let form=document.getElementById('storyPublicForm'),vibe=form?.querySelector('[name="vibe_styles"]'),step=vibe?.closest('.brief-step');if(!form||!step||step.querySelector('[data-visual-identity-v419]'))return;storyVisualIdentityFilesV419=sbArr(x?.briefing?.visual_identity_files).filter(file=>String(file?.path||'').includes('/briefing/visual-identity/')).slice(0,6);let section=document.createElement('section');section.className='visual-identity-public';section.dataset.visualIdentityV419='';section.innerHTML=`<small class="ey">IDENTIDADE VISUAL DO CASAMENTO</small><h3>Tem algum material visual para compartilhar?</h3><p>Se vocês já tiverem monograma, paleta de cores, convite ou outro material da identidade visual, podem enviar aqui. Isso ajuda a manter os Stories e conteúdos alinhados ao estilo do casamento.</p><div class="visual-identity-picker"><label class="btn ghost small">＋ Adicionar arquivos<input type="file" hidden multiple accept=".pdf,.jpg,.jpeg,.png,.webp,.heic,.heif,application/pdf,image/jpeg,image/png,image/webp,image/heic,image/heif" onchange="sbUploadVisualIdentityV419(this)"></label><small>PDF ou imagem · até 6 arquivos · 10 MB cada</small></div><div class="visual-identity-list" data-visual-identity-list></div><small class="visual-identity-status" data-visual-identity-status></small>`;step.querySelector('.brief-actions')?.before(section);let originalSubmit=form.onsubmit;form.onsubmit=function(ev){if(form.dataset.visualIdentityUploading==='true'){ev.preventDefault();return alert('Aguarde os arquivos terminarem de enviar.')}return originalSubmit.call(form,ev)};sbRenderVisualIdentityV419()}

const _storyRenderVisualIdentityV419Base=renderStoryPublic;
renderStoryPublic=function(x,token){_storyRenderVisualIdentityV419Base(x,token);sbAddVisualIdentityV419(x)};

const _storyDetailVisualIdentityV419Base=storymakerDetailModal;
storymakerDetailModal=function(id){let html=_storyDetailVisualIdentityV419Base(id),b=(D.storyBriefings||[]).find(x=>x.event_id===id),files=sbArr(b?.visual_identity_files).filter(file=>String(file?.path||'').includes('/briefing/visual-identity/'));if(!html||!files.length)return html;let block=`<div class="story-op-block wide"><h4>IDENTIDADE VISUAL DO CASAMENTO</h4><div class="visual-identity-internal">${files.map(file=>`<button type="button" class="btn ghost small" onclick="openFile('${E(file.path)}')">${E(file.name||'Abrir arquivo')} ↗</button>`).join('')}</div></div>`,needle='<div class="story-op-block wide"><h4>TRENDS E INSPIRAÇÕES</h4>';return html.includes(needle)?html.replace(needle,block+needle):html.replace('<div class="story-op-block wide"><h4>REFERÊNCIAS</h4>',block+'<div class="story-op-block wide"><h4>REFERÊNCIAS</h4>')};

