function sbDeliveryModeActiveV421(x){let params=new URLSearchParams(location.search),eventData=x?.event||{},status=String(eventData.delivery_status||'pending'),hasLinks=['delivery_raw_url','delivery_edited_url','delivery_photos_url','delivery_folder_url'].some(key=>Boolean(sbSafeDeliveryUrlV420(eventData[key])));return params.get('preview')==='entrega'||hasLinks||status==='organizing'||status==='delivered'}
function sbApplyDeliveryModeV421(x){if(!sbDeliveryModeActiveV421(x))return;let page=document.querySelector('.story-public'),hero=page?.querySelector('.hero'),progress=page?.querySelector('.brief-progress'),form=document.getElementById('storyPublicForm');if(!page||!hero)return;page.classList.add('delivery-mode-v421');if(progress){progress.hidden=true;progress.setAttribute('aria-hidden','true')}if(form){form.hidden=true;form.setAttribute('aria-hidden','true')}let intro=hero.querySelector('.intro');if(intro)intro.textContent='Os materiais da cobertura de vocês ficam reunidos aqui para acessar, baixar e guardar com facilidade. 🧡'}

